function safe(s){return String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[m]));}
function publicYouthText(value){return String(value??"").replace(/\bunder\s*21\b/gi,"Under 23").replace(/\bu21\b/gi,"U23");}
