const IMAGE_FALLBACK_SRC="/img/placeholder.webp";
document.addEventListener("error", function(event){
  const img = event && event.target;
  if(!img || !img.tagName || img.tagName.toLowerCase() !== "img") return;
  if(img.dataset && img.dataset.fallbackApplied === "1") return;
  if(img.dataset) img.dataset.fallbackApplied = "1";
  img.src = IMAGE_FALLBACK_SRC;
}, true);

function teamKey(name){return String(name||"").toLowerCase().replace(/[^a-z0-9]/g,"");}
function isCusTeam(name){const k=teamKey(name);return k==="custrento"||k==="custrentoc5"||k==="custrentou21"||k.includes("custrento");}
function paginate(items,page,perPage){const total=Math.max(1,Math.ceil((items||[]).length/perPage));const safePage=Math.min(Math.max(1,page||1),total);return {total,page:safePage,items:(items||[]).slice((safePage-1)*perPage,safePage*perPage)};}
function pagerHtml(total,page,fn){
  total=Number(total)||1;
  page=Number(page)||1;
  if(total<=1)return "";

  const safePage=Math.min(Math.max(1,page),total);
  const prev=Math.max(1,safePage-1);
  const next=Math.min(total,safePage+1);

  return `<div class="smart-pager" aria-label="Paginazione">
    <button class="pill" ${safePage===1?"disabled":""} onclick="${fn}(1)" title="Prima pagina">« Prima</button>
    <button class="pill" ${safePage===1?"disabled":""} onclick="${fn}(${prev})" title="Pagina precedente">‹</button>

    <label class="page-jump">
      <span>Pagina</span>
      <input
        type="number"
        min="1"
        max="${total}"
        value="${safePage}"
        inputmode="numeric"
        aria-label="Vai alla pagina"
        onkeydown="if(event.key==='Enter'){${fn}(parseInt(this.value,10)||1)}"
        onchange="${fn}(parseInt(this.value,10)||1)"
      >
      <span>di ${total}</span>
    </label>

    <button class="pill" ${safePage===total?"disabled":""} onclick="${fn}(${next})" title="Pagina successiva">›</button>
    <button class="pill" ${safePage===total?"disabled":""} onclick="${fn}(${total})" title="Ultima pagina">Ultima »</button>
  </div>`;
}

function esc(v){return String(v ?? "").replace(/[&<>"']/g, ch => ({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[ch]));}
function socialPlatformLabel(platform){const p=String(platform||"").toLowerCase();return p.includes("tiktok")?"TikTok":"Instagram";}
