function articleBlockHtml(block){
  const type=String(block&&block.type||"").toLowerCase();
  const image=block&&block.image;
  const text=block&&block.text;
  const caption=block&&block.caption;
  if((type==="image"||image) && image){
    return `<figure class="article-inline-image"><img loading="lazy" decoding="async" src="${image}" alt="${safe(caption||'Immagine articolo')}">${caption?`<figcaption>${safe(caption)}</figcaption>`:""}</figure>`;
  }
  if(text)return `<p>${safe(text)}</p>`;
  return "";
}
function articleContentHtml(n, paragraphs){
  if(n.bodyHtml)return String(n.bodyHtml);
  if(Array.isArray(n.contentBlocks)&&n.contentBlocks.length){
    const html=n.contentBlocks.map(articleBlockHtml).join("");
    if(html.trim())return html;
  }
  return paragraphs.map(p=>`<p>${safe(p)}</p>`).join("");
}
function articleDetail(id){
  const n=findNewsById(id);
  if(!n){route("news");return;}
  const paragraphs=Array.isArray(n.body)?n.body:String(n.body||n.excerpt||"").split("\n").filter(Boolean);
  const tagBox=`<div class="badge-row" style="margin:0 0 14px">${newsTags(n).map(t=>`<span class="badge">${safe(t)}</span>`).join("")}</div>`;
  const sourceBox=n.sourceUrl?`<div class="source-box"><b>Fonte:</b> <a href="${n.sourceUrl}" target="_blank" rel="noopener noreferrer">${n.sourceName||"SporTrentino.it"}</a></div>`:"";
  const articleContent=articleContentHtml(n,paragraphs);
  shell(n.category||"News",n.title||"Articolo",`<div class="breadcrumb"><button class="back-link" onclick="route('news')"><span>←</span> News</button></div>${tagBox}${sourceBox}${newsShareButtons(n)}<img class="article-hero" loading="lazy" decoding="async" src="${n.image||''}" alt="${safe(n.title||'News')}"><div class="grid grid" style="margin-top:28px"><article class="card card-pad article-body imported-article">${articleContent}<div class="article-share-bottom">${newsShareButtons(n)}</div></article></div>`, "", n.excerpt||`${n.title||"Articolo"} — CUS Trento C5`, n.image);
}

function playerMetricsCard(p){
  if(p.role==="Portiere"&&p.goalkeeperStats){
    return `<div class="metrics"><div class="metric"><b>${p.appearances||0}</b><small>Presenze</small></div><div class="metric gk-mini"><b>${p.goalkeeperStats.goalsAgainst||0}</b><small>Gol subiti</small></div></div>`;
  }
  return `<div class="metrics"><div class="metric"><b>${p.appearances||0}</b><small>Presenze</small></div><div class="metric"><b>${p.goals||0}</b><small>Reti</small></div></div>`;
}
function rosterCardNameHtml(p){
  const parts=String(p&&p.name||"").trim().split(/\s+/).filter(Boolean);
  let surnameParts=parts.slice(0,1);
  if(parts.length>=2&&parts[0].toLowerCase()==="baccaro"&&parts[1].toLowerCase()==="zeni")surnameParts=parts.slice(0,2);
  const givenParts=parts.slice(surnameParts.length);
  const surname=surnameParts.join(" ");
  const given=givenParts.join(" ");
  return `<span class="player-card-surname">${safe(surname)}</span>${given?` <span class="player-card-given">${safe(given)}</span>`:""}`;
}
