const MEDIA_SEASONS=["2025/26","2026/27"];
const CURRENT_MEDIA_SEASON="2026/27";
const MEDIA_CATEGORY_OPTIONS={
  gallery:["Tutte","Prima squadra","Under 23","Partite","Interviste","CNU","Vario"],
  video:["Tutte","Prima squadra","Under 23","Partite","Interviste","CNU","Vario"]
};
function mediaCategoriesFor(kind){return MEDIA_CATEGORY_OPTIONS[kind]||MEDIA_CATEGORY_OPTIONS.gallery;}
function mediaSeasonOf(item){return String(item.season||item.stagione||"2025/26");}
function mediaCategoryLabels(item){
  const raw=Array.isArray(item.categories)?item.categories:[];
  const labels=raw.map(x=>publicYouthText(String(x||"").trim())).filter(Boolean);
  if(labels.length)return labels;
  const legacy=String(item.category||item.type||"").trim();
  if(!legacy)return ["Tutte"];
  const c=normText(legacy);
  if(c.includes("u21")||c.includes("u23")||c.includes("under"))return ["Under 23"];
  if(c.includes("prima"))return ["prima squadra"];
  if(c.includes("cnu"))return ["CNU"];
  if(c.includes("interview")||c.includes("intervist"))return ["interviste"];
  if(c.includes("match")||c.includes("partit")||c.includes("highlight"))return ["partite"];
  return ["vario"];
}
function mediaCategoryKeys(item){return mediaCategoryLabels(item).map(normText);}
function mediaCategoryBadges(item){return mediaCategoryLabels(item).filter(x=>normText(x)!=="tutte");}
function mediaMatches(item,season,category){
  if(mediaSeasonOf(item)!==season)return false;
  const cat=normText(category||"Tutte");
  if(cat==="tutte")return true;
  return mediaCategoryKeys(item).includes(cat);
}
function mediaFilters(kind){const seasonKey=kind==="gallery"?"gallerySeason":"videoSeason";const catKey=kind==="gallery"?"galleryCategory":"videoCategory";const setSeason=kind==="gallery"?"setGallerySeason":"setVideoSeason";const setCat=kind==="gallery"?"setGalleryCategory":"setVideoCategory";return `<div class="media-filter-block"><div class="media-filter-label">Stagione</div><div class="toolbar media-toolbar">${MEDIA_SEASONS.map(x=>`<button class="pill ${view[seasonKey]===x?"active":""}" onclick="${setSeason}('${x}')">${x}</button>`).join("")}</div><div class="media-filter-label">Categoria</div><div class="toolbar media-toolbar">${mediaCategoriesFor(kind).map(x=>`<button class="pill ${view[catKey]===x?"active":""}" onclick="${setCat}('${x}')">${x}</button>`).join("")}</div></div>`;}
function setGallerySeason(season){view.gallerySeason=season;view.galleryPage=1;gallery();}
function setGalleryCategory(cat){view.galleryCategory=cat;view.galleryPage=1;gallery();}
function goGalleryPage(page){view.galleryPage=page;renderGalleryList();}
function renderGalleryList(){if(!MEDIA_SEASONS.includes(view.gallerySeason))view.gallerySeason=CURRENT_MEDIA_SEASON;const items=(state.galleryAlbums||[]).filter(g=>mediaMatches(g,view.gallerySeason||CURRENT_MEDIA_SEASON,view.galleryCategory||"Tutte"));const pg=paginate(items,view.galleryPage,6);view.galleryPage=pg.page;const grid=$("#galleryGrid"),pager=$("#galleryPager");if(grid)grid.innerHTML=galleryCards(pg.items)||"<div class='card card-pad'><p class='muted'>Nessun contenuto per questi filtri.</p></div>";if(pager)pager.innerHTML=pagerHtml(pg.total,pg.page,"goGalleryPage");}
function galleryPhotoSrc(photo){return typeof photo==="string"?photo:(photo&&(photo.u||photo.url||photo.photo||photo.image||photo.src))||"";}
function galleryPhotos(album){return (album&&Array.isArray(album.photos)?album.photos:[]).map(galleryPhotoSrc).filter(Boolean);}
function galleryCards(items){return items.map(g=>{const badges=mediaCategoryBadges(g);const photos=galleryPhotos(g);return `<article class="card gallery-card clickable" onclick="route('gallery-album-${objectSlug(g,'galleryAlbums')}')"><span class="album-count">${photos.length} foto</span><img loading="lazy" class="gallery-img" src="${g.cover}" alt="${g.title}"><div class="gallery-caption"><div class="badge-row">${badges.length?badges.map(c=>`<span class="badge">${c}</span>`).join(""):`<span class="badge">Tutte</span>`}</div><h2 style="margin-top:10px">${g.title}</h2><p>${fmt(g.date)}</p></div></article>`}).join("");}
function gallery(){shell("Media gallery","Gallery fotografiche",`${mediaFilters('gallery')}<div class="grid grid-3" id="galleryGrid"></div><div id="galleryPager"></div>`,"","Gallery fotografiche CUS Trento C5.");renderGalleryList();}
function galleryAlbum(id){const g=findObjectBySlug(state.galleryAlbums||[],"galleryAlbums",id);if(!g){route("gallery");return;}const photos=galleryPhotos(g);shell("Gallery",g.title,`<div class="breadcrumb"><button class="back-link" onclick="route('gallery')"><span>←</span> Gallery</button></div><div class="grid grid-3" style="margin-top:24px">${photos.map((src,i)=>`<article class="card clickable" onclick="openLightbox('${objectSlug(g,'galleryAlbums')}',${i})"><img loading="lazy" class="gallery-img" src="${src}" alt="${g.title} foto ${i+1}"><div class="card-pad"><span class="badge">Foto ${i+1}</span></div></article>`).join("")}</div>`,"","Album fotografico CUS Trento C5.",g.cover);}
function setVideoSeason(season){view.videoSeason=season;view.videoPage=1;videos();}
function setVideoCategory(cat){view.videoCategory=cat;view.videoPage=1;videos();}
function videos(){shell("Video","Highlights, interviste e contenuti social video",`${mediaFilters('video')}<div class="grid grid-3" id="videoGrid"></div><div id="videoPager"></div>`,"","Video e highlights CUS Trento C5.");renderVideoList();}
function youtubeThumb(url){
  const embed = youtubeEmbedUrl(url || "");
  const match = embed.match(/\/embed\/([^?]+)/);
  if (!match) return "";
  return `https://img.youtube.com/vi/${decodeURIComponent(match[1])}/hqdefault.jpg`;
}

