function moveClubHistory(delta){const imgs=(state.clubHistory&&state.clubHistory.images)||[];if(!imgs.length)return;view.clubHistoryIndex=(view.clubHistoryIndex+delta+imgs.length)%imgs.length;club();}
function club(){
  const clubHistoryData = (state.clubHistory && typeof state.clubHistory === "object") ? state.clubHistory : {};
  const fallbackHistoryParagraphs = ["Il CUS Trento C5 è la sezione ufficiale di calcio 5 dell’ASD CUS Trento e con le sue squadre rappresenta l’Università degli Studi di Trento nei campionati FIGC e nei campionati nazionali universitari. La sezione nasce nella stagione 2011/2012 dall’idea di un gruppo di amici e studenti universitari, uniti dalla voglia di portare il futsal dentro la realtà del CUS Trento. Da una passione condivisa prende forma una squadra giovane, legata all’ambiente universitario e costruita su impegno, correttezza e spirito di gruppo.", "L’esordio arriva nel campionato di Serie D, chiuso al decimo posto sia nella stagione 2011/2012 sia in quella successiva. Fin dai primi passi, però, emerge un’identità chiara: il risultato conta, ma conta anche il modo in cui si rappresenta il club. Nel primo anno di partecipazione arriva infatti anche la Coppa Disciplina, segnale di un progetto fondato sui valori dello sport.", "La prima svolta arriva nella stagione 2013/2014, quando il CUS Trento chiude al primo posto il girone A di Serie D e conquista la promozione in Serie C2 nella stagione successiva. L’esperienza in categoria superiore si rivela formativa ma complessa: al termine del campionato la squadra viene sconfitta ai play-out e riparte dalla Serie D.", "Negli anni successivi il progetto continua a crescere. Nella stagione 2015/2016 il CUS Trento raggiunge la semifinale play-off. La promozione arriva al termine della stagione 2016/2017, confermando il percorso di maturazione della squadra.", "Dopo alcune stagioni complicate, segnate anche dalle limitazioni del periodo COVID, il CUS Trento C5 riprende il proprio cammino con continuità. Al termine della stagione 2021/2022 arriva la promozione in Serie C1, categoria in cui la squadra milita attualmente.", "Il punto più alto del percorso sportivo arriva nella stagione 2025/2026, la migliore nella storia della sezione: il CUS Trento C5 chiude al secondo posto in Serie C1 e si gioca l’accesso alla Serie B nel triangolare promozione. Un risultato che racconta la crescita del club e conferma la solidità di un progetto nato tra studenti universitari, ma capace di competere con ambizione nel futsal regionale."];
  const historyTitle = clubHistoryData.title || "La nostra storia";
  const historyParagraphs = Array.isArray(clubHistoryData.paragraphs) && clubHistoryData.paragraphs.length ? clubHistoryData.paragraphs : fallbackHistoryParagraphs;
  const projectTitle="Il Progetto";
  const projectParagraphs=["Il CUS Trento C5 è un progetto sportivo nato per unire futsal, università e territorio. Non è soltanto una squadra che partecipa ai campionati: è un ambiente in cui studenti, giovani atleti e appassionati possono crescere, competere e sentirsi parte di una community.", "La nostra missione è offrire agli studenti-atleti un percorso sportivo di qualità, capace di accompagnare la loro crescita personale, universitaria e umana. Il campo diventa uno spazio educativo: un luogo in cui allenare responsabilità, spirito di squadra, disciplina, benessere e capacità che valgono anche fuori dallo sport.", "La visione del CUS Trento C5 è costruire un polo attrattivo per studenti-atleti, creando un ecosistema in cui università, territorio e imprese possano collaborare. Il futsal diventa così un ponte tra formazione, competenze e opportunità: un progetto che guarda alla crescita sportiva, ma anche al futuro personale e professionale dei suoi protagonisti.", "Oggi il CUS Trento C5 continua a crescere attraverso la prima squadra, il percorso Under 23, le competizioni universitarie, gli eventi, la comunicazione e le collaborazioni. L’obiettivo è diventare un punto di riferimento stabile per il futsal universitario trentino: una realtà capace di formare atleti, coinvolgere persone e rappresentare con orgoglio il CUS Trento e l’Università degli Studi di Trento."];
  const historicImages=((state.clubHistory&&state.clubHistory.images)||[]).filter(x=>x&&x.image);
  const idx=Math.min(Math.max(view.clubHistoryIndex||0,0),Math.max(historicImages.length-1,0));
  const currentImg=historicImages[idx]||{};
  const renderParagraphs=items=>items.map(p=>`<p class="muted" style="margin-bottom:16px">${esc(p)}</p>`).join("");
  const projectGallery=historicImages.length?`<div class="club-project-mini-gallery" style="margin:22px auto 0;max-width:43%;width:100%;border-radius:18px;overflow:hidden;border:1px solid rgba(0,0,0,.08);background:#fff"><div class="clickable" onclick="openLightbox('club-history',${idx})"><img loading="lazy" src="${esc(currentImg.image)}" alt="Rosa CUS Trento ${esc(currentImg.season||'')}" style="height:190px;width:100%;object-fit:cover"><div style="display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:14px 0 0"><div><span class="badge">${esc(currentImg.season||'Archivio')}</span><p class="muted" style="margin:8px 0 0">Rose storiche CUS Trento · ${idx+1} di ${historicImages.length}</p></div><div class="btns" style="margin:0"><button class="btn soft" onclick="event.stopPropagation();moveClubHistory(-1)">←</button><button class="btn soft" onclick="event.stopPropagation();moveClubHistory(1)">→</button></div></div></div></div>`:"";
  shell("Club","Chi siamo",`<div class="grid grid-2"><article class="card card-pad"><span class="eyebrow">Storia</span><h2 style="margin-bottom:16px">${esc(historyTitle)}</h2>${renderParagraphs(historyParagraphs)}</article><article class="card card-pad"><span class="eyebrow">Progetto</span><h2 style="margin-bottom:16px">${esc(projectTitle)}</h2>${renderParagraphs(projectParagraphs)}${projectGallery}</article></div>` ,"","Storia e progetto sportivo del CUS Trento C5.");
}
function getCookieChoice(){
  const choice=localStorage.getItem("cus_cookie_choice");
  if(choice) return choice;
  return localStorage.getItem("cus_cookie_ok")?"all":"";
}
function hasThirdPartyConsent(){return getCookieChoice()==="all";}
function openCookieDetails(){const modal=$("#cookieModal");if(modal)modal.classList.add("show");}
function closeCookieDetails(){const modal=$("#cookieModal");if(modal)modal.classList.remove("show");}
function acceptCookies(choice="all"){
  const normalized=choice==="necessary"?"necessary":"all";
  localStorage.setItem("cus_cookie_choice",normalized);
  localStorage.setItem("cus_cookie_ok","yes");
  closeCookieDetails();
  if(current==="matchday")render();
}
function rejectCookies(){acceptCookies("necessary");}
function resetCookieConsent(){
  localStorage.removeItem("cus_cookie_choice");
  localStorage.removeItem("cus_cookie_ok");
  closeCookieDetails();
  if(current==="matchday")render();
}

