// ===== CMS BOOT: carica i contenuti pubblicati da content/data.json + archivio news importate =====
function newsKeyForMerge(n){
  return String(
    (n && (n.sourceUrl || n._sportrentino_source_url || n.sourceId || n.id)) ||
    `${n && n.title || ""}|${n && n.date || ""}`
  );
}

function sortNewsForFrontend(news){
  return [...(news || [])].sort((a,b)=>{
    const da = String(a && a.date || "");
    const db = String(b && b.date || "");
    if(db !== da) return db.localeCompare(da);
    return Number(b && b.id || 0) - Number(a && a.id || 0);
  });
}

function mergeCmsNewsWithImportedArchive(cmsNews, importedNews){
  const merged = [];
  const seen = new Set();

  // Prima le news del CMS: se una news nuova viene importata in data.json, vince su eventuali copie archiviate.
  (cmsNews || []).forEach(n=>{
    const key = newsKeyForMerge(n);
    if(!seen.has(key)){
      seen.add(key);
      merged.push(n);
    }
  });

  // Poi l'archivio storico read-only, che non deve appesantire il CMS.
  (importedNews || []).forEach(n=>{
    const key = newsKeyForMerge(n);
    if(!seen.has(key)){
      seen.add(key);
      merged.push(n);
    }
  });

  return sortNewsForFrontend(merged);
}

async function loadImportedNewsArchive(){
  try{
    const res = await fetch('/content/news.imported.json', {cache:'no-cache'});
    if(!res.ok){
      console.warn(`content/news.imported.json non caricato: HTTP ${res.status}. Il sito userà solo le news CMS.`);
      return [];
    }

    const raw = await res.text();
    const archive = JSON.parse(raw);
    if(Array.isArray(archive)) return archive;
    if(archive && Array.isArray(archive.news)) return archive.news;
    return [];
  }catch(e){
    console.warn("Errore caricamento content/news.imported.json. Il sito userà solo le news CMS.", e);
    return [];
  }
}

async function loadImportedNewsIndex(){
  try{
    const res = await fetch('/content/news.index.json', {cache:'no-cache'});
    if(!res.ok){
      if(res.status !== 404) console.warn(`content/news.index.json non caricato: HTTP ${res.status}.`);
      return [];
    }
    const raw = await res.text();
    const payload = JSON.parse(raw);
    if(Array.isArray(payload)) return payload;
    if(payload && Array.isArray(payload.news)) return payload.news;
    return [];
  }catch(e){
    console.warn("Errore caricamento content/news.index.json. Il sito userà solo le news CMS fino al caricamento dell'archivio.", e);
    return [];
  }
}

let importedNewsArchivePromise = null;
function upgradeNewsWithFullArchive(existingNews, importedArchiveNews){
  const fullByKey = new Map((importedArchiveNews || []).map(n => [newsKeyForMerge(n), n]));
  const upgraded = (existingNews || []).map(n => {
    const full = fullByKey.get(newsKeyForMerge(n));
    if(full && (full.bodyHtml || (Array.isArray(full.body) && full.body.length))){
      return {...n, ...full};
    }
    return n;
  });
  return mergeCmsNewsWithImportedArchive(upgraded, importedArchiveNews || []);
}
function scheduleImportedNewsArchiveLoad(delayMs){
  if(importedNewsArchivePromise) return importedNewsArchivePromise;
  importedNewsArchivePromise = new Promise(resolve => {
    const run = async function(){
      const importedArchiveNews = await loadImportedNewsArchive();
      if(importedArchiveNews && importedArchiveNews.length){
        state.news = upgradeNewsWithFullArchive(state.news || [], importedArchiveNews);
        if(current === "news" || current.startsWith("article-")) render();
      }
      resolve(importedArchiveNews || []);
    };
    const delay = Number.isFinite(delayMs) ? Math.max(0, delayMs) : 3000;
    setTimeout(run, delay);
  });
  return importedNewsArchivePromise;
}

async function loadSocialFeed(){
  try{
    const res = await fetch('/content/social-feed.json', {cache:'no-cache'});
    if(!res.ok){
      console.warn(`content/social-feed.json non caricato: HTTP ${res.status}. Il sito userà il social fallback.`);
      return [];
    }
    const raw = await res.text();
    const payload = JSON.parse(raw);
    if(Array.isArray(payload)) return payload;
    if(payload && Array.isArray(payload.posts)) return payload.posts;
    return [];
  }catch(e){
    console.warn("Errore caricamento content/social-feed.json. Il sito userà il social fallback.", e);
    return [];
  }
}


async function bootData(){
  let dataLoaded = false;
  let loadError = null;
  const preservePrerenderedArticle = String(current||"").startsWith("article-") && app && app.dataset.prerendered === "true";

  try{
    const res = await fetch('/content/data.json', {cache:'no-cache'});
    if(!res.ok) throw new Error(`content/data.json non caricato: HTTP ${res.status}`);

    const raw = await res.text();
    // content/data.json è pubblicato già unito ai file content/cms/*.json (scripts/site_data.py merge).
    const published = normalizePublishedData(JSON.parse(raw));
    const [importedNewsIndex, latestSocialFeed] = await Promise.all([
      loadImportedNewsIndex(),
      loadSocialFeed()
    ]);

    // Prima render veloce: usiamo l'indice leggero delle news, non l'archivio completo con bodyHtml.
    // Il testo completo degli articoli viene caricato dopo il primo render o quando l'utente apre le news.
    published.news = mergeCmsNewsWithImportedArchive(published.news || [], importedNewsIndex);
    published.socialFeed = latestSocialFeed.length ? latestSocialFeed : (published.socialFeed || legacySocialToFeed(published.social || []));

    state = applyAutomations(hydrate(published));     // i dati pubblicati hanno priorita' e vengono incrementati dai match terminati
    dataLoaded = true;

    if(current === "news" || current.startsWith("article-")) scheduleImportedNewsArchiveLoad(0);
  }catch(e){
    loadError = e;
    console.error("Errore caricamento content/data.json. Il sito sta usando i defaults interni di app.js.", e);
  }

  if(!preservePrerenderedArticle) render();

  if(!dataLoaded && app){
    app.insertAdjacentHTML("afterbegin", `
      <section class="container" style="padding-top:24px">
        <div class="card card-pad" style="border:2px solid #ef4444">
          <span class="eyebrow">Errore dati CMS</span>
          <h2>content/data.json non è stato caricato correttamente</h2>
          <p class="muted">Il sito sta mostrando i dati di fallback presenti in app.js. Controlla che content/data.json sia JSON valido e pubblicato nella cartella corretta.</p>
          <pre style="white-space:pre-wrap;background:#111;color:#fff;padding:14px;border-radius:12px;overflow:auto">${String(loadError && loadError.message || loadError)}</pre>
        </div>
      </section>
    `);
  }

}
// ===== LINK REALI: i pulsanti che chiamano route('...') diventano <a href>, così crawler,
// "apri in nuova scheda" e tasto destro vedono l'URL canonico; il click resta gestito dal router.
function routeIdFromOnclick(raw){const m=String(raw||"").match(/(?:cusMenuRoute|route)\(['"]([^'"]+)['"]\)/);return m?m[1]:"";}
function linkifyRouteButtons(root){
  (root||document).querySelectorAll("button[onclick]").forEach(button=>{
    const routeId=routeIdFromOnclick(button.getAttribute("onclick"));
    if(!routeId) return;
    const a=document.createElement("a");
    Array.from(button.attributes||[]).forEach(attr=>{if(!["onclick","type"].includes(attr.name)) a.setAttribute(attr.name,attr.value);});
    a.href=appPathForRoute(routeId);
    a.innerHTML=button.innerHTML;
    a.dataset.cusRealLink="1";
    a.addEventListener("click",event=>{
      if(event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey) return;
      event.preventDefault();
      route(routeId);
    });
    button.replaceWith(a);
  });
}

